let file = """{"version":3,"file":"hostTelemetryEnabled-rmY6auRV.js","names":[],"sources":["../../src/utils/devFeatureFlagOverride.ts","../../src/platform/telemetry/hostTelemetryEnabled.ts"],"sourcesContent":["const FF_PREFIX = 'ff:'\n\n/**\n * Gets a dev-time feature flag override from localStorage.\n * Stripped from production builds via import.meta.env.DEV tree-shaking.\n *\n * Returns undefined (not null) as the \"no override\" sentinel because\n * null is a valid JSON value — JSON.parse('null') returns null.\n * Using undefined avoids ambiguity between \"no override set\" and\n * \"override explicitly set to null\".\n *\n * Usage in browser console:\n *   localStorage.setItem('ff:example_enabled', 'true')\n *   localStorage.removeItem('ff:example_enabled')\n */\nexport function getDevOverride<T>(\n  flagKey: string & { readonly valueType?: T }\n): T | undefined {\n  if (!import.meta.env.DEV || typeof localStorage === 'undefined')\n    return undefined\n  let raw: string | null\n  try {\n    raw = localStorage.getItem(`${FF_PREFIX}${flagKey}`)\n  } catch {\n    return undefined\n  }\n  if (raw === null) return undefined\n  try {\n    return JSON.parse(raw) as T\n  } catch {\n    console.warn(`[ff] Invalid JSON for override \"${flagKey}\":`, raw)\n    return undefined\n  }\n}\n","import { remoteConfig } from '@/platform/remoteConfig/remoteConfig'\nimport { getDevOverride } from '@/utils/devFeatureFlagOverride'\n\nconst ENABLE_TELEMETRY_FEATURE = 'enable_telemetry'\n\nexport function isHostTelemetryEnabled(): boolean {\n  const override = getDevOverride<boolean>(ENABLE_TELEMETRY_FEATURE)\n  if (override !== undefined) return override\n\n  return remoteConfig.value.enable_telemetry === true\n}\n"],"mappings":"sFAeA,SAAgB,eACd,EACe,CAgBjB,CC5BA,SAAgB,wBAAkC,CAIhD,OAAO,EAAa,MAAM,mBAAqB,EACjD"}"""

